/// <summary>
/// MPJ_20036
/// </summary>
public class METOrderExtractScreenTmp extends common
{
}

Method.Source:
    /// <summary>
    /// To calculate and display the number of cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of cases</returns>
    [SysClientCacheDataMethod(true)]
    public display METCase METCases()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        InventItemSalesSetup    inventItemSalesSetup;
        InventDim               inventDimSetup;
        METSalesLine            metSalesLineLoc;
        METCase                 metCase = 0;

        select sum(SalesQty) from salesLineLoc
                where salesLineLoc.SalesId == this.SalesId
                && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join lineInventDim 
                where lineInventDim.inventDimId == salesLineLoc.InventDimId
            join inventItemSalesSetup 
                where inventItemSalesSetup.ItemId == salesLineLoc.ItemId
                && inventItemSalesSetup.METSalesUnit == salesLineLoc.salesUnit
                && inventItemSalesSetup.METAltSalesUnit != salesLineLoc.salesUnit
            exists join inventDimSetup 
                where inventDimSetup.InventDimId == inventItemSalesSetup.InventDimId
                && inventDimSetup.InventSiteId == lineInventDim.InventSiteId
            exists join metSalesLineLoc
                where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted;

        metCase = any2Int(salesLineLoc.SalesQty);
        
        return metCase;
    }

    /// <summary>
    /// To calculate and display the number of broken cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of broken cases</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METBrokenCase METBrokenCase()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        InventItemSalesSetup    inventItemSalesSetup;
        InventDim               inventDimSetup;
        METSalesLine            metSalesLineLoc;
        METBrokenCase           metBrokenCase = 0;

        select sum(SalesQty) from salesLineLoc
            where salesLineLoc.SalesId == this.SalesId
            && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join lineInventDim where lineInventDim.inventDimId == salesLineLoc.InventDimId
            join inventItemSalesSetup where inventItemSalesSetup.ItemId == salesLineLoc.ItemId
                && inventItemSalesSetup.METSalesUnit != salesLineLoc.salesUnit
                && inventItemSalesSetup.METAltSalesUnit == salesLineLoc.salesUnit
            exists join inventDimSetup where inventDimSetup.InventDimId == inventItemSalesSetup.InventDimId
                && inventDimSetup.InventSiteId == lineInventDim.InventSiteId
            exists join metSalesLineLoc where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted;

        metBrokenCase = any2Int(salesLineLoc.SalesQty);

        return metBrokenCase;
    }

    /// <summary>
    /// To calculate and display the number of broken cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of broken cases</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METBrokenCase METActualBrokenCase()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        InventItemSalesSetup    inventItemSalesSetup;
        InventDim               inventDimSetup;
        METBrokenCase           estimatedBrokenCases = 0;
        InventTransId           inventTransId;
        SalesId                 salesId = this.SalesId;
        METSalesLine            metSalesLineLoc;
        METCase                 actualCases = 0;
        UnitOfMeasureSymbol     unitInvent;
        InventQty               reservedQty = 0;
        InventQty               onOrderQty = 0;
        InventQty               priorityQty = 0;
        METInventTransView      views;

        // Calculate for each sales line in this SalesId
        while select salesUnit, InventTransId, ItemId, RecId from salesLineLoc
            where salesLineLoc.SalesId == this.SalesId
                && salesLineLoc.SalesStatus == SalesStatus::Backorder
        join lineInventDim
            where lineInventDim.inventDimId == salesLineLoc.InventDimId
        join METSalesUnit, METAltSalesUnit, InventDimId from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLineLoc.ItemId
        exists join inventDimSetup
            where inventDimSetup.InventDimId == inventItemSalesSetup.InventDimId
            && inventDimSetup.InventSiteId == lineInventDim.InventSiteId
        exists join metSalesLineLoc where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            // Only process alternate unit orders (broken cases logic)
            if (!(inventItemSalesSetup.METSalesUnit != salesLineLoc.salesUnit &&
                 inventItemSalesSetup.METAltSalesUnit == salesLineLoc.salesUnit))
            {
                continue;
            }

            inventTransId = salesLineLoc.InventTransId;
            reservedQty = 0;
            onOrderQty = 0;
            priorityQty = 0;

            // Step 1: Query Reservation quantity (ReservPhysical + ReservOrdered)
            select sum(Qty) from views
            where views.ReferenceId == salesId
            && views.inventTransId == inventTransId
            && (views.StatusIssue == StatusIssue::ReservPhysical
                || views.StatusIssue == StatusIssue::ReservOrdered);

            reservedQty = abs(views.Qty);

            // Step 2: Prioritize Reservation; if zero, use On Order
            if (reservedQty > 0)
            {
                priorityQty = reservedQty;
            }
            else
            {
                // Query On Order quantity as fallback
                select sum(Qty) from views
                where views.ReferenceId == salesId
                && views.inventTransId == inventTransId
                && views.StatusIssue == StatusIssue::OnOrder;

                onOrderQty = abs(views.Qty);
                priorityQty = onOrderQty;
            }

            // Step 3: Convert to cases and calculate broken cases
            if (priorityQty != 0)
            {
                unitInvent = InventTableModule::find(salesLineLoc.ItemId, ModuleInventPurchSales::Invent).UnitId;
                actualCases = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                salesLineLoc.ItemId,
                salesLineLoc.inventDimId,
                priorityQty,
                unitInvent,
                inventItemSalesSetup.METSalesUnit,
                NoYes::No,
                NoYes::No);
                
                estimatedBrokenCases += priorityQty - actualCases;
            }
        }

        return estimatedBrokenCases;
    }

    /// <summary>
    /// To calculate and display the number of cases for the sales order line quantity.
    /// </summary>
    /// <returns>Number of cases</returns>
    [SysClientCacheDataMethod(true)]
    public display METCase METActualCases()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        InventItemSalesSetup    inventItemSalesSetup;
        InventDim               inventDimSetup;
        METInventTransView      views;
        UnitOfMeasureSymbol     unitInvent;
        METSalesLine            metSalesLineLoc;
        METCase                 actualCases = 0;
        
        while select salesUnit, ItemId, InventTransId, inventDimId, SalesId from salesLineLoc 
                where salesLineLoc.SalesId == this.SalesId
                    && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join lineInventDim 
                where lineInventDim.inventDimId == salesLineLoc.InventDimId
            join inventItemSalesSetup 
                where inventItemSalesSetup.ItemId == salesLineLoc.ItemId
                && inventItemSalesSetup.METSalesUnit == salesLineLoc.salesUnit
                && inventItemSalesSetup.METAltSalesUnit != salesLineLoc.salesUnit
            exists join inventDimSetup 
                where inventDimSetup.InventDimId == inventItemSalesSetup.InventDimId
                && inventDimSetup.InventSiteId == lineInventDim.InventSiteId
            exists join metSalesLineLoc where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            InventQty reservedQty = 0;

            // Combine both status checks in a single query using 'in' clause
            select sum(Qty) from views
            where views.ReferenceId == salesLineLoc.SalesId
                && views.inventTransId == salesLineLoc.InventTransId
                && (views.StatusIssue == StatusIssue::ReservPhysical
                    || views.StatusIssue == StatusIssue::ReservOrdered
                    || views.StatusIssue == StatusIssue::OnOrder);

            reservedQty = abs(views.Qty);

            if (reservedQty != 0)
            {
                unitInvent = InventTableModule::find(salesLineLoc.ItemId, ModuleInventPurchSales::Invent).UnitId;
                actualCases += EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(salesLineLoc.ItemId, salesLineLoc.inventDimId, reservedQty, unitInvent, salesLineLoc.SalesUnit, NoYes::No, NoYes::No);
            }
        }
        
        return actualCases;
    }

    /// <summary>
    /// To get actualWeight for the SalesLine Item.
    /// </summary>
    /// <returns>ActualWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METGrossWeight METOrderedWeight()
    {
        SalesLine               salesLineLoc;
        METSalesLine            metsalesLineLoc;
        Weight                  weight;

        while select SalesQty from salesLineLoc 
                where salesLineLoc.SalesId == this.SalesId
                && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join SalesUnitWeight from metsalesLineLoc 
                where metsalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metsalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            weight += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitWeight;
        } 

        return weight;
    }

    /// <summary>
    /// To get ActualUnitVolume for the SalesLine Item.
    /// </summary>
    /// <returns>unitVolume of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUOMVolume METOrderedVolume()
    {
        SalesLine               salesLineLoc;
        METSalesLine            metsalesLineLoc;
        Volume                  volume;

        while select SalesQty from salesLineLoc 
                where salesLineLoc.SalesId == this.SalesId
                && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join SalesUnitVolume from metsalesLineLoc 
                where metsalesLineLoc.SalesLine == salesLineLoc.RecId
                && metSalesLineLoc.LineCancellationRequired == NoYes::No
                && metsalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            volume += salesLineLoc.SalesQty * metsalesLineLoc.SalesUnitVolume;
        }

        return volume;
    }

    /// <summary>
    /// To get ActualUnitVolume for the SalesLine Item.
    /// </summary>
    /// <returns>unitVolume of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METUOMVolume METActualUnitVolume()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        METUOMVolume            metActualUOMVolume = 0;
        ItemId                  itemId;
        UnitOfMeasureSymbol     unitSales;
        UnitOfMeasureSymbol     unitInvent;
        InventQty               actCase; 
        InventQty               actBrokenCase; 
        METSalesLine            metSalesLineLoc;

        METUOMVolume caseVolume = METWHSPhysDimUOMSite::convertVolume(itemId, actCase, unitSales, lineInventDim);
        METUOMVolume brokenCaseVolume = METWHSPhysDimUOMSite::convertVolume(itemId, actBrokenCase, unitInvent, lineInventDim);

        while select ItemId, salesUnit, InventTransId, inventDimId, SalesId from salesLineLoc 
                where salesLineLoc.SalesId == this.SalesId
                    && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join lineInventDim 
                where lineInventDim.inventDimId == salesLineLoc.InventDimId
            exists join metSalesLineLoc where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                    && metSalesLineLoc.LineCancellationRequired == NoYes::No
                    && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            itemId          = salesLineLoc.ItemId;
            unitSales       = salesLineLoc.SalesUnit;
            unitInvent      = InventTableModule::find(itemId, ModuleInventPurchSales::Invent).UnitId;

            actCase         = salesLineLoc.displayMETActualCases();
            actBrokenCase   = salesLineLoc.displayMETActualBrokenCase();

            caseVolume = METWHSPhysDimUOMSite::convertVolume(itemId, actCase, unitSales, lineInventDim);
            brokenCaseVolume = METWHSPhysDimUOMSite::convertVolume(itemId, actBrokenCase, unitInvent, lineInventDim);

            metActualUOMVolume += (caseVolume + brokenCaseVolume);
        }

        return metActualUOMVolume;
    }

    /// <summary>
    /// To get actualWeight for the SalesLine Item.
    /// </summary>
    /// <returns>ActualWeight of salesLine Item</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display METGrossWeight METActualWeight()
    {
        SalesLine               salesLineLoc;
        InventDim               lineInventDim;
        METSalesLine            metSalesLineLoc;
        METGrossWeight          metActualWeight = 0;

        while select RecId, salesUnit, ItemId, InventTransId, inventDimId, SalesId from salesLineLoc 
                where salesLineLoc.SalesId == this.SalesId
                    && salesLineLoc.SalesStatus == SalesStatus::Backorder
            join lineInventDim 
                where lineInventDim.inventDimId == salesLineLoc.InventDimId
            exists join metSalesLineLoc where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                    && metSalesLineLoc.LineCancellationRequired == NoYes::No
                    && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
        {
            UnitOfMeasureSymbol unitSales = salesLineLoc.SalesUnit;
            METSalesLine metSalesLine = METSalesLine::find(salesLineLoc.RecId);
   

            // Prefer actual/captured weights if available
            if (metSalesLine.CWActualWeight != 0.0)
            {
                metActualWeight += metSalesLine.CWActualWeight;
                continue;
            }
            if (metSalesLine.AISWeight != 0.0)
            {
                metActualWeight += metSalesLine.AISWeight;
                continue;
            }

            UnitOfMeasureSymbol unitInvent = InventTableModule::find(salesLineLoc.ItemId, ModuleInventPurchSales::Invent).UnitId;

            // Cache actual case and broken case quantities
            InventQty actCase = salesLineLoc.displayMETActualCases();
            InventQty actBrokenCase = salesLineLoc.displayMETActualBrokenCase();

            // Calculate and return total actual weight
            METGrossWeight caseWeight = METWHSPhysDimUOMSite::convertWeight(salesLineLoc.ItemId, actCase, unitSales, lineInventDim);
            METGrossWeight brokenCaseWeight = METWHSPhysDimUOMSite::convertWeight(salesLineLoc.ItemId, actBrokenCase, unitInvent, lineInventDim);

            metActualWeight += (caseWeight + brokenCaseWeight);
        }

        return metActualWeight;
    }
